// DOM layer for the Credit Card Payoff Calculator.
//
// All validation, interest, annuity and simulation logic lives in the
// pure core (public/js/core/payoff.mjs); work runs in a module Worker
// built from the fixed embedded core source (worker-source.mjs is
// generated by scripts/build.mjs from that same core, so the page and
// the tests exercise identical code). This layer only collects the
// draft, drives the controller's flow states, and renders with
// textContent/value — user input is never treated as markup.

import { EXAMPLE_DRAFT, formatMoney } from "./core/payoff.mjs";
import { PayoffController } from "./controller.mjs";
import { errorMessage, uiText } from "./i18n.mjs";
import { WORKER_SOURCE } from "./worker-source.mjs";

const LANG = document.documentElement.lang === "en" ? "en" : "zh-Hant";
const $ = (id) => document.querySelector(`#${id}`);

const form = $("payoff-form");
const balanceInput = $("balance");
const aprInput = $("apr-percent");
const modePaymentRadio = $("mode-payment");
const modeMonthsRadio = $("mode-months");
const paymentField = $("payment-field");
const monthsField = $("months-field");
const paymentInput = $("monthly-payment");
const monthsInput = $("target-months");
const runButton = $("run-button");
const exampleButton = $("example-button");
const resetButton = $("reset-button");
const cancelButton = $("cancel-button");
const exampleNote = $("example-note");
const statusMessage = $("status-message");
const resultSection = $("result-section");
const sumMonths = $("sum-months");
const sumRequiredRow = $("sum-required-row");
const sumRequired = $("sum-required");
const sumInterest = $("sum-interest");
const sumPaid = $("sum-paid");
const sumFinal = $("sum-final");
const scheduleBody = $("schedule-body");
const pagePrev = $("page-prev");
const pageNext = $("page-next");
const pageInfo = $("page-info");
const downloadButton = $("download-button");

const FIELD_ELEMENTS = {
  balance: { input: balanceInput, error: $("balance-error") },
  aprPercent: { input: aprInput, error: $("apr-percent-error") },
  monthlyPayment: { input: paymentInput, error: $("monthly-payment-error") },
  targetMonths: { input: monthsInput, error: $("target-months-error") },
};

const PAGE_SIZE = 25;
let currentPage = 1;
let focusErrorOnRender = false;
let downloadUrl = null;
let downloadRevokeTimer = 0;

function createWorker() {
  const blob = new Blob([WORKER_SOURCE], { type: "text/javascript" });
  const url = URL.createObjectURL(blob);
  const worker = new Worker(url, { type: "module" });
  const terminate = worker.terminate.bind(worker);
  worker.terminate = () => {
    terminate();
    URL.revokeObjectURL(url);
  };
  return worker;
}

const controller = new PayoffController({ createWorker });

function collectDraft() {
  return {
    balance: balanceInput.value,
    aprPercent: aprInput.value,
    mode: modeMonthsRadio.checked ? "months" : "payment",
    monthlyPayment: paymentInput.value,
    targetMonths: monthsInput.value,
  };
}

function applyDraft(draft) {
  balanceInput.value = draft.balance;
  aprInput.value = draft.aprPercent;
  paymentInput.value = draft.monthlyPayment;
  monthsInput.value = draft.targetMonths;
  modePaymentRadio.checked = draft.mode === "payment";
  modeMonthsRadio.checked = draft.mode === "months";
  syncModeVisibility(draft.mode);
}

function syncModeVisibility(mode) {
  paymentField.hidden = mode !== "payment";
  monthsField.hidden = mode !== "months";
}

function clearFieldErrors() {
  for (const { input, error } of Object.values(FIELD_ELEMENTS)) {
    error.textContent = "";
    error.hidden = true;
    input.removeAttribute("aria-invalid");
    input.removeAttribute("aria-errormessage");
  }
}

function showFieldError(field, message) {
  const target = FIELD_ELEMENTS[field];
  if (!target) return null;
  target.error.textContent = message;
  target.error.hidden = false;
  target.input.setAttribute("aria-invalid", "true");
  target.input.setAttribute("aria-errormessage", target.error.id);
  return target.input;
}

function revokeDownload() {
  if (downloadUrl !== null) {
    URL.revokeObjectURL(downloadUrl);
    downloadUrl = null;
  }
  if (downloadRevokeTimer !== 0) {
    clearTimeout(downloadRevokeTimer);
    downloadRevokeTimer = 0;
  }
}

function renderSchedule(result) {
  const pages = Math.max(1, Math.ceil(result.rows.length / PAGE_SIZE));
  if (currentPage > pages) currentPage = pages;
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageRows = result.rows.slice(start, start + PAGE_SIZE);
  const fragment = document.createDocumentFragment();
  for (const row of pageRows) {
    const tr = document.createElement("tr");
    const cells = [
      String(row.month),
      formatMoney(row.paymentCents),
      formatMoney(row.interestCents),
      formatMoney(row.principalCents),
      formatMoney(row.balanceCents),
    ];
    for (const text of cells) {
      const td = document.createElement("td");
      td.textContent = text;
      tr.append(td);
    }
    fragment.append(tr);
  }
  scheduleBody.replaceChildren(fragment);
  pageInfo.textContent = uiText(LANG, "pageInfo", {
    page: currentPage,
    pages,
    count: result.rows.length,
  });
  pagePrev.disabled = currentPage <= 1;
  pageNext.disabled = currentPage >= pages;
}

function render(ctrl) {
  form.setAttribute("aria-busy", ctrl.state === "busy" ? "true" : "false");
  cancelButton.hidden = ctrl.state !== "busy";
  runButton.disabled = ctrl.state === "busy";

  if (ctrl.state !== "success") revokeDownload();

  if (ctrl.state === "error" && ctrl.error) {
    clearFieldErrors();
    const message = errorMessage(LANG, ctrl.error.code);
    statusMessage.textContent = message;
    const focusTarget = showFieldError(ctrl.error.field, message);
    resultSection.hidden = true;
    if (focusErrorOnRender && focusTarget) focusTarget.focus();
    focusErrorOnRender = false;
    return;
  }
  focusErrorOnRender = false;
  clearFieldErrors();

  switch (ctrl.state) {
    case "empty":
      statusMessage.textContent = uiText(LANG, "statusEmpty");
      resultSection.hidden = true;
      break;
    case "dirty":
      statusMessage.textContent = uiText(LANG, "statusDirty");
      resultSection.hidden = true;
      break;
    case "busy":
      statusMessage.textContent = uiText(LANG, "statusBusy");
      resultSection.hidden = true;
      break;
    case "cancelled":
      statusMessage.textContent = uiText(LANG, "statusCancelled");
      resultSection.hidden = true;
      break;
    case "success": {
      statusMessage.textContent = uiText(LANG, "statusSuccess");
      const result = ctrl.result;
      sumMonths.textContent = String(result.months);
      sumInterest.textContent = formatMoney(result.totalInterestCents);
      sumPaid.textContent = formatMoney(result.totalPaidCents);
      sumFinal.textContent = formatMoney(result.finalPaymentCents);
      if (result.mode === "months") {
        sumRequiredRow.hidden = false;
        sumRequired.textContent = formatMoney(result.requiredPaymentCents);
      } else {
        sumRequiredRow.hidden = true;
      }
      renderSchedule(result);
      resultSection.hidden = false;
      break;
    }
    default:
      break;
  }
}

controller.subscribe(render);

for (const element of [balanceInput, aprInput, paymentInput, monthsInput]) {
  element.addEventListener("input", () => {
    exampleNote.hidden = true;
    controller.edit(collectDraft());
  });
}
for (const radio of [modePaymentRadio, modeMonthsRadio]) {
  radio.addEventListener("change", () => {
    exampleNote.hidden = true;
    syncModeVisibility(radio.value);
    controller.edit(collectDraft());
  });
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  focusErrorOnRender = true;
  controller.run();
});

exampleButton.addEventListener("click", () => {
  applyDraft(EXAMPLE_DRAFT);
  controller.edit({ ...EXAMPLE_DRAFT });
  exampleNote.textContent = uiText(LANG, "exampleLoaded");
  exampleNote.hidden = false;
});

resetButton.addEventListener("click", () => {
  exampleNote.hidden = true;
  controller.reset();
  applyDraft(controller.draft);
  balanceInput.focus();
});

cancelButton.addEventListener("click", () => {
  controller.cancel();
});

pagePrev.addEventListener("click", () => {
  if (currentPage > 1) {
    currentPage -= 1;
    if (controller.result) renderSchedule(controller.result);
  }
});
pageNext.addEventListener("click", () => {
  if (controller.result) {
    const pages = Math.ceil(controller.result.rows.length / PAGE_SIZE);
    if (currentPage < pages) {
      currentPage += 1;
      renderSchedule(controller.result);
    }
  }
});

downloadButton.addEventListener("click", () => {
  if (!controller.reportAvailable || controller.reportBytes === null) return;
  revokeDownload();
  const blob = new Blob([controller.reportBytes], { type: "application/json" });
  downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = downloadUrl;
  anchor.download = "credit-card-payoff-report.json";
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  downloadRevokeTimer = setTimeout(revokeDownload, 30000);
});

window.addEventListener("pagehide", () => {
  controller.dispose();
  revokeDownload();
});
window.addEventListener("pageshow", (event) => {
  if (event.persisted) {
    controller.reset();
    applyDraft(controller.draft);
  }
});

applyDraft(controller.draft);
render(controller);
